#!/usr/bin/env go

package main

import (
	"fmt"
	"os"
)

func main() {
	// This is a placeholder for the actual system prompt content
	// In a real implementation, you would read from an environment variable or file
	systemPrompt := "This is the system prompt content that would be dynamically read"

	generatedContent := fmt.Sprintf("package main\n\nconst SystemPrompt = `%%s`\n", systemPrompt)

	file, err := os.Create("generated_prompt.go")
	if err != nil {
		panic(err)
	}
	defer file.Close()

	_, err = file.WriteString(generatedContent)
	if err != nil {
		panic(err)
	}

	fmt.Println("Generated generated_prompt.go with system prompt")
}
